+    Migrated,
+    /// A rule that could be migrated if `--include-inspired` was passed
+    Inspired,
+    /// A rule that could be migrated if `--include-nursery` was passed
+    Nursery,
+    /// An unsupported rule
+    Unsupported,
+}
